"""Low level user interaction functions for the 3D Dicom Import Validation Tool window. Used by the DicomImportValidation page object class"""

from .objects.xvi_service_objects import Dicom3DImportObjects
from interops.libraries.squish_actions import CommonActions
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import XVI_APP_NAME


def __find_main_dicom_3d_import_validation_tool_window():
    """Searches for the main Dicom Import Validation Tool window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the dicom_3d_import_tool_functions.py file

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Dicom3DImportObjects.dicom_3D_Import_Dialog) is not None else False

def __find_dicom_3d_import_selected_dicom_set_check_dialog(wait_timeout: int):
    """Searches for the Selected DICOM set check Dialog. Returns True if successfully located.

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.wait_for_object_exists(Dicom3DImportObjects.dicom_3D_Import_Selected_Dicom_Set_Check_Dialog, wait_timeout) is not None else False

def __locate_dicom_set_list_item_by_child_object_index(childObjIndex: int) -> object:
    """Searches the Dicom Set list view pane child objects based on the positional index and returns the
    ListViewItem object if successfully located. Assumes that the ordering of the child objects remains constant.

    Used for selecting dicom data set item in the list to import.

    :param int childObjIndex: Index of the ListViewItem child object in the Dicom Set ListView pane object
    :return: found object
    :rtype: object
    """
    if __find_main_dicom_3d_import_validation_tool_window():
        dicom_set_list_pane_obj_list = CommonActions.get_child_objects(Dicom3DImportObjects.dicom_Set_List_Pane)

        if len(dicom_set_list_pane_obj_list) > 0:
            dicom_data_set_item_object = dicom_set_list_pane_obj_list[childObjIndex]
            return dicom_data_set_item_object

def wait_for_main_dicom_3d_import_validation_tool_window(wait_timeout: int) -> bool:
    """Waits for the main Dicom Import Validation Tool window to exist. Returns True if successfully located.
    """
    return True if CommonActions.wait_for_object_exists(Dicom3DImportObjects.dicom_3D_Import_Dialog, wait_timeout) is not None else False

# --------------------------------------- Dicom Set List interactions ---------------------------------------

@deco.set_separate_app_context(application_name=XVI_APP_NAME)
def select_dicom_data_set_item(dicom_data_set_count_number: int=1) -> None:
    """Locates the main Dicom Import Validation Tool window > selects the specified Dicom data set item based on
    Set Count number from the Dicom Set List pane

    :param str dicom_data_set_count_number: Dicom Data Set count number to be selected. Index starts at 1
    """
    if __find_main_dicom_3d_import_validation_tool_window():
        dicom_data_set_item_obj = __locate_dicom_set_list_item_by_child_object_index(childObjIndex=dicom_data_set_count_number)
        CommonActions.left_click_object_no_move(dicom_data_set_item_obj)

